<?php
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/cash_lots.php';require_once __DIR__.'/../includes/cash_layout.php';
$user=require_role(ROLE_FINANCE,ROLE_SUPER_ADMIN);
if(is_post()){
 csrf_verify();try{
  if(!password_verify(input('password'),$user['password_hash']))throw new DomainException('Confirm your administrator password.');
  cash_lot_plan_save((int)$user['id'],(int)input('id'),input('name'),input('price'),input('capacity'),input('timeframe_days'),input('daily_earnings_percent'),input('enabled'),input('referral_percent'));
  flash_set('success','Lot package saved. Timeframe and daily earnings are snapshotted when a trader purchases the Lot.');
 }catch(DomainException $e){flash_set('error',$e->getMessage());}catch(Throwable $e){error_log('[Lot plan save] '.$e->getMessage());flash_set('error','Unable to save. Import the Lot timeframe and Lot referral bonus migrations first.');}
 redirect('/admin/lot-plans.php');
}
cash_header($user,'Lot Packages');
try{if(!referral_lot_ensure_schema())throw new RuntimeException('Per-Lot referral columns missing.');$plans=cash_query('SELECT * FROM cash_lot_plans ORDER BY id')->fetchAll();}catch(Throwable $e){echo '<div class="notice">Import the Lot timeframe and Lot referral bonus database updates first.</div>';cash_footer();exit;}
$sample=input('sample')==='1';
$plans[]=['id'=>0,'name'=>$sample?'Sample Starter Lot':'','price_minor'=>$sample?1000:0,'capacity'=>$sample?5:1,'timeframe_days'=>$sample?30:30,'daily_earnings_bps'=>$sample?300:0,'referral_bps'=>null,'enabled'=>$sample?1:0];
?>
<section class="panel cash-body"><h3>Lot Package settings</h3><p>Create Lot packages and configure the earning timeframe and percentage per Lot per day. The daily earning is divided across 24 hourly periods. Each Lot package can have its own referral bonus percentage. A purchased Lot keeps the terms that were active at the exact time of purchase.</p><a class="button" href="/admin/lot-plans.php?sample=1#new-package">Use sample: $10 · 5 spaces · 30 days · 3%/day</a> <a class="button secondary" href="/admin/referrals.php">Lot Referral Bonus Setup</a></section>
<div class="dashboard-grid"><?php foreach($plans as $p): $hourlyEstimate=(int)$p['price_minor']*(int)($p['daily_earnings_bps']??0)/10000/24; ?><section class="panel cash-body" id="<?= $p['id']?'package-'.(int)$p['id']:'new-package' ?>"><h3><?= $p['id']?'Edit package #'.(int)$p['id']:'Add Lot package' ?></h3><p><span class="chip"><?= $p['enabled']?'Enabled':'Disabled' ?></span></p><form method="post" action="/admin/lot-plans.php"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><label>Name<input name="name" maxlength="100" value="<?= e($p['name']) ?>" required></label><label>Price (USD)<input name="price" type="number" min="1" max="1000000" step="0.01" value="<?= $p['price_minor']?e(number_format($p['price_minor']/100,2,'.','')):'' ?>" required></label><label>Product spaces<input name="capacity" type="number" min="1" max="1000" value="<?= (int)$p['capacity'] ?>" required></label><label>Timeframe (days)<input name="timeframe_days" type="number" min="1" max="3650" value="<?= (int)($p['timeframe_days']??30) ?>" required></label><label>Earnings per Lot per day (%)<input name="daily_earnings_percent" type="number" min="0" max="100" step="0.01" value="<?= e(number_format(((int)($p['daily_earnings_bps']??0))/100,2,'.','')) ?>" required></label><label>Referral bonus for this Lot (%)<input name="referral_percent" type="number" min="0" max="100" step="0.01" placeholder="Blank = global setting" value="<?= ($p['referral_bps']??null)===null?'':e(number_format(((int)$p['referral_bps'])/100,2,'.','')) ?>"></label><p class="fine-print">Paid to the referrer on each purchase of this Lot. Leave blank to use the global Lot Referral Bonus setting.</p><p class="fine-print">Current estimate: <?= cash_money((int)round($hourlyEstimate)) ?> per completed hour, divided from the configured daily amount. No compounding.</p><label>Status<select name="enabled"><option value="0">Disabled</option><option value="1" <?= $p['enabled']?'selected':'' ?>>Enabled</option></select></label><label>Your admin password<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Save Lot package</button></form></section><?php endforeach ?></div>
